    "What documentation do I need for vehicle rental collections?": "レンタカーの受け取りにはどのような書類が必要ですか？",
    "You must present a valid passport, a driver's license held for a minimum of 1 year, and a valid Credit Card under the main driver's name. Renters must be 21 years or older, and some performance vehicle tiers require an age of 25.": "有効なパスポート、取得から1年以上経過した運転免許証、メインドライバー名義の有効なクレジットカードを提示する必要があります。レンタルは21歳以上の方に限られ、一部の高性能車両クラスでは25歳以上であることが求められます。",
    "What is your refund and cancellation policy?": "返金およびキャンセルのポリシーを教えてください。",
    "Our tours and holiday packages are fully flexible. You can cancel or make changes to your booking dates up to 14 days prior to departure without incurring any cancellation fees from Premier Tour. Air ticket refunds are subject to individual carrier guidelines.": "当社のツアーや休暇パッケージは完全に柔軟です。出発の14日前までであれば、プレミアツアーからのキャンセル料なしで予約のキャンセルや日程の変更が可能です。航空券の払い戻しは、各航空会社のガイドラインに従います。",
    "How do I receive my booking confirmations and travel vouchers?": "予約確認書やトラベルバウチャーはどのように受け取りますか？",
    "Once you complete your payment on Premier Tour Booking, a confirmation email with your digital itinerary, e-tickets, and rental vouchers will be sent instantly to your registered email address. You can also view, print, and track all your active booking history from your Customer Dashboard.": "プレミアツアーブッキングでの支払いが完了すると、デジタル日程表、Eチケット、レンタルバウチャーが記載された確認メールが登録されたメールアドレスに即座に送信されます。また、カスタマーダッシュボードからすべてのアクティブな予約履歴を表示、印刷、追跡することもできます。",
    "Are flights and accommodations ATOL protected?": "航空券や宿泊施設はATOLの保護を受けていますか？",
    "Yes! All flight packages, holidays, and hotel stays arranged through Premier Tour Booking are fully protected under our ABTA and ATOL Bonding certifications, ensuring complete financial security for your journey.": "はい！プレミアツアーブッキングを通じて手配されたすべてのフライトパッケージ、休暇、ホテル滞在は、当社のABTAおよびATOLボンド認証の下で完全に保護されており、ご旅行の完全な財務的セキュリティを保証します。",
    "Do you offer customizable travel dates and layouts?": "旅行の日程やプランはカスタマイズ可能ですか？",
    "Absolutely. If you require specialized dates, custom hotel room configurations, multi-destination stopovers, or private charter vehicle setups, please submit a Contact Form or contact our 24/7 travel desk at +94 76 166 8155.": "もちろんです。特別な日程、カスタムのホテルの部屋の構成、複数目的地の途中降機、またはプライベートチャーター車のセットアップが必要な場合は、お問い合わせフォームを送信するか、24時間年中無休のトラベルデスク（+94 76 166 8155）までご連絡ください。",
