    "Experience pure bliss in an overwater villa. Includes private snorkeling tours, sunset dolphin cruise, and candlelit beach dinners.": "水上ヴィラで至福のひとときを。プライベートシュノーケリングツアー、サンセットドルフィンクルーズ、キャンドルライトビーチディナーが含まれます。",
    "Istanbul Imperial Heritage": "イスタンブール帝国の遺産",
    "Immerse yourself in the rich history of Istanbul. Visit the iconic Hagia Sophia, Blue Mosque, Topkapi Palace, and experience a Bosphorus cruise.": "イスタンブールの豊かな歴史に浸ってください。象徴的なアヤソフィア、ブルーモスク、トプカプ宮殿を訪れ、ボスポラス海峡クルーズを体験します。",
