    "Experience Bali's mystical cultural heart. Hike through Tegalalang Rice Terraces, seek blessings at Tirta Empul, and watch Kechak fire dance.": "バリの神秘的な文化の中心を体験してください。テガラランライステラスをハイキングし、ティルタウンプルで祝福を求め、ケチャックファイヤーダンスを鑑賞します。",
