    "Wander through the historic labyrinth of Stone Town, smell exotic spices, and swim with sea turtles in Nungwi.": "歴史的なストーンタウンの迷宮をさまよい、エキゾチックなスパイスの香りを嗅ぎ、ヌングイでウミガメと泳ぎます。",
