    "What documentation do I need for vehicle rental collections?": "Welche Unterlagen benötige ich für die Abholung von Mietwagen?",
    "You must present a valid passport, a driver's license held for a minimum of 1 year, and a valid Credit Card under the main driver's name. Renters must be 21 years or older, and some performance vehicle tiers require an age of 25.": "Sie müssen einen gültigen Reisepass, einen seit mindestens 1 Jahr gültigen Führerschein und eine gültige Kreditkarte auf den Namen des Hauptfahrers vorlegen. Mieter müssen mindestens 21 Jahre alt sein, für einige Leistungsklassen ist ein Alter von 25 Jahren erforderlich.",
    "What is your refund and cancellation policy?": "Wie lauten Ihre Rückerstattungs- und Stornierungsbedingungen?",
    "Our tours and holiday packages are fully flexible. You can cancel or make changes to your booking dates up to 14 days prior to departure without incurring any cancellation fees from Premier Tour. Air ticket refunds are subject to individual carrier guidelines.": "Unsere Touren und Urlaubspakete sind voll flexibel. Sie können Ihre Buchung bis zu 14 Tage vor der Abreise stornieren oder ändern, ohne dass Stornogebühren von Premier Tour anfallen. Rückerstattungen für Flugtickets unterliegen den Richtlinien der jeweiligen Fluggesellschaft.",
    "How do I receive my booking confirmations and travel vouchers?": "Wie erhalte ich meine Buchungsbestätigungen und Reiseunterlagen?",
    "Once you complete your payment on Premier Tour Booking, a confirmation email with your digital itinerary, e-tickets, and rental vouchers will be sent instantly to your registered email address. You can also view, print, and track all your active booking history from your Customer Dashboard.": "Sobald Sie Ihre Zahlung bei Premier Tour Booking abgeschlossen haben, wird eine Bestätigungs-E-Mail mit Ihrem digitalen Reiseplan, E-Tickets und Mietgutscheinen sofort an Ihre registrierte E-Mail-Adresse gesendet. Sie können auch Ihren gesamten aktiven Buchungsverlauf über Ihr Kunden-Dashboard anzeigen, ausdrucken und verfolgen.",
    "Are flights and accommodations ATOL protected?": "Sind Flüge und Unterkünfte ATOL-geschützt?",
    "Yes! All flight packages, holidays, and hotel stays arranged through Premier Tour Booking are fully protected under our ABTA and ATOL Bonding certifications, ensuring complete financial security for your journey.": "Ja! Alle Flugpakete, Urlaube und Hotelaufenthalte, die über Premier Tour Booking arrangiert werden, sind durch unsere ABTA- und ATOL-Zertifizierungen vollständig geschützt und gewährleisten so vollständige finanzielle Sicherheit für Ihre Reise.",
    "Do you offer customizable travel dates and layouts?": "Bieten Sie anpassbare Reisedaten und Reiseverläufe an?",
    "Absolutely. If you require specialized dates, custom hotel room configurations, multi-destination stopovers, or private charter vehicle setups, please submit a Contact Form or contact our 24/7 travel desk at +94 76 166 8155.": "Absolut. Wenn Sie spezielle Reisedaten, benutzerdefinierte Hotelzimmerkonfigurationen, Zwischenstopps an mehreren Reisezielen oder private Charterfahrzeuge benötigen, senden Sie bitte ein Kontaktformular ein oder kontaktieren Sie unseren rund um die Uhr besetzten Reiseservice unter +94 76 166 8155.",
    "Founded Year": "Gründungsjahr",
