    "Luxury overwater villas, private infinity pools, and world-class fine dining overlooking the azure Indian Ocean.": "Luxuriöse Überwasservillen, private Infinity-Pools und Weltklasse-Gastronomie mit Blick auf den azurblauen Indischen Ozean.",
