    "A secluded sanctuary of clean lines and natural materials, tucked into the red-rock canyons of the American Southwest.": "Ein abgeschiedenes Refugium aus klaren Linien und natürlichen Materialien, versteckt in den roten Felsenschluchten des amerikanischen Südwestens.",
