    "A historic luxury landmark on Fifth Avenue offering refined guest rooms, fine dining, and prestigious white-glove service.": "Ein historisches Luxus-Wahrzeichen an der Fifth Avenue, das elegante Gästezimmer, feines Essen und erstklassigen White-Glove-Service bietet.",
