    "Maldives Overwater Sanctuary": "Malediven-Überwasser-Refugium",
    "Experience pure bliss in an overwater villa. Includes private snorkeling tours, sunset dolphin cruise, and candlelit beach dinners.": "Erleben Sie pure Glückseligkeit in einer Überwasservilla. Beinhaltet private Schnorcheltouren, Delfinkreuzfahrten bei Sonnenuntergang und Abendessen am Strand bei Kerzenschein.",
    "Istanbul Imperial Heritage": "Kaiserliches Erbe Istanbuls",
    "Immerse yourself in the rich history of Istanbul. Visit the iconic Hagia Sophia, Blue Mosque, Topkapi Palace, and experience a Bosphorus cruise.": "Tauchen Sie ein in die reiche Geschichte Istanbuls. Besuchen Sie die ikonische Hagia Sophia, die Blaue Moschee, den Topkapi-Palast und erleben Sie eine Bosporus-Kreuzfahrt.",
    "Sri Lanka Wild & Historic": "Sri Lanka Wild & Historisch",
    "An action-packed adventure through Sigiriya Rock, Kandy Temple, and a wildlife safari in Yala National Park.": "Ein actiongeladenes Abenteuer durch den Sigiriya-Felsen, den Kandy-Tempel und eine Wildtiersafari im Yala-Nationalpark.",
    "Bali Sacred Temples & Ubud": "Heilige Tempel von Bali & Ubud",
    "Experience Bali's mystical cultural heart. Hike through Tegalalang Rice Terraces, seek blessings at Tirta Empul, and watch Kechak fire dance.": "Erleben Sie Balis mystisches kulturelles Herz. Wandern Sie durch die Reisterrassen von Tegalalang, suchen Sie Segen in Tirta Empul und schauen Sie sich den Kechak-Feuertanz an.",
    "Zanzibar Stone Town & Spices": "Sansibar Stone Town & Gewürze",
    "Wander through the historic labyrinth of Stone Town, smell exotic spices, and swim with sea turtles in Nungwi.": "Schlendern Sie durch das historische Labyrinth von Stone Town, riechen Sie exotische Gewürze und schwimmen Sie mit Meeresschildkröten in Nungwi.",
    "Santorini Volcanic Caldera": "Vulkanische Caldera von Santorini",
    "Sail across the deep-blue Aegean Sea. Swim in natural hot springs, sample fine volcanic wines, and watch Oia sunsets.": "Segeln Sie über die tiefblaue Ägäis. Schwimmen Sie in natürlichen heißen Quellen, probieren Sie feine vulkanische Weine und beobachten Sie die Sonnenuntergänge von Oia.",
