    "YOUR DREAM JOURNEY": "LE VOYAGE DE VOS RÊVES",
    "At Premier Tour Booking, we believe flexibility is the key to perfect travel planning. Whether you want to stay in an ultra-luxurious overwater villa in the Maldives, wander the historic bazaars of Istanbul, or embark on a wild safari in Sri Lanka, we connect all details together to make it painless.": "Chez Premier Tour Booking, nous pensons que la flexibilité est essentielle à une planification de voyage parfaite. Que vous souhaitiez séjourner dans une villa sur pilotis ultra-luxueuse aux Maldives, vous promener dans les bazars historiques d'Istanbul ou embarquer pour un safari au Sri Lanka, nous nous occupons de tout.",
    "Our state-of-the-art booking system brings real-time rates directly from verified hotels, airlines, and premium vehicle operators, helping you secure the best prices with fully custom dates, and customizable payment structures.": "Notre système de réservation de pointe vous propose des tarifs en temps réel provenant d'hôtels, de compagnies aériennes et d'agences de location de véhicules vérifiés, vous aidant à obtenir les meilleurs prix avec des dates et des paiements personnalisables.",
