    "Frequently Asked Questions": "Häufig gestellte Fragen (FAQ)",
    "What is your refund and cancellation policy?": "Wie lauten Ihre Rückerstattungs- und Stornierungsbedingungen?",
    "How do I receive my booking confirmations and travel vouchers?": "Wie erhalte ich meine Buchungsbestätigungen und Reisegutscheine?",
    "Our Legacy": "Unser Vermächtnis",
    "Our Mission & Story": "Unsere Mission & Geschichte",
    "Learn about Premier Tour Booking's global commitment to handcrafting dream journeys.": "Erfahren Sie mehr über das weltweite Engagement von Premier Tour Booking für handgefertigte Traumreisen.",
    "Perfecting Travel Since 2018": "Perfektes Reisen seit 2018",
    "Premier Tour Booking was established in 2018 with a humble, powerful vision: to take the complexity out of custom international travel. What began as a local boutique consultation firm has matured into a comprehensive digital portal servicing over 120,000 satisfied passengers globally.": "Premier Tour Booking wurde 2018 mit einer bescheidenen, kraftvollen Vision gegründet: die Komplexität aus maßgeschneiderten internationalen Reisen zu nehmen. Was als lokales Boutique-Beratungsunternehmen begann, hat sich zu einem umfassenden digitalen Portal entwickelt, das weltweit über 120.000 zufriedene Passagiere betreut.",
    "We specialize in bridging flights, bespoke hotel partnerships, guided adventures, and premium vehicle fleets into cohesive, flexible itineraries. By bypassing traditional middlemen, we are able to maintain a premium standard of services while extending best-in-market rates directly to our travelers.": "Wir sind darauf spezialisiert, Flüge, maßgeschneiderte Hotelpartnerschaften, geführte Abenteuer und Premium-Fahrzeugflotten zu harmonischen, flexiblen Reiserouten zu verbinden. Durch die Umgehung traditioneller Zwischenhändler können wir ein erstklassiges Serviceniveau aufrechterhalten und gleichzeitig die besten Preise auf dem Markt direkt an unsere Reisenden weitergeben.",
    "Our core values are anchored on transparency, environmental sustainability, and meticulous customer care. With 24/7 global client support centers and an active flight tracking network, we make sure that our passengers are covered at every mile of their voyage.": "Unsere Grundwerte basieren auf Transparenz, ökologischer Nachhaltigkeit und sorgfältiger Kundenbetreuung. Mit rund um die Uhr erreichbaren globalen Support-Centern und einem aktiven Flugverfolgungssystem sorgen wir dafür, dass unsere Passagiere auf jeder Meile ihrer Reise bestens betreut sind.",
    "Our Standards": "Unsere Standards",
    "Why Choose Premier Tour": "Warum Premier Tour wählen",
    "Four pillars that define our service excellence and travel quality.": "Vier Säulen, die unsere Service-Exzellenz und Reisequalität definieren.",
    "Trusted Experience": "Bewährte Erfahrung",
    "Over 8 years of continuous booking experience, verified tour experts, and ATOL/ABTA protected travel networks.": "Über 8 Jahre kontinuierliche Buchungserfahrung, verifizierte Reiseexperten und ATOL/ABTA-geschützte Reisenetzwerke.",
    "24/7 Live Support": "24/7 Live-Support",
    "Immediate concierge support in London, Dubai, and Singapore to handle cancellations or re-routing instantly.": "Sofortige Concierge-Unterstützung in London, Dubai und Singapur für die sofortige Bearbeitung von Stornierungen oder Umbuchungen.",
