    "Includes professional English-speaking driver, fuel, highway tolls, passenger liability insurance, and 24/7 breakdown support.": "Inklusive professionellem englischsprachigem Fahrer, Treibstoff, Autobahngebühren, Insassenversicherung und 24/7-Pannenhilfe.",
    "Premium luxury sedan with leather interior, dual-zone climate control, bottled water, and private English-speaking chauffeur.": "Erstklassige Luxuslimousine mit Lederausstattung, 2-Zonen-Klimaautomatik, Trinkwasser und privatem englischsprachigem Chauffeur.",
    "Spacious high-roof van ideal for families or group tours with ample luggage space, rear AC, and experienced tour driver.": "Geräumiger Hochdach-Van, ideal für Familien oder Gruppenreisen mit reichlich Gepäckraum, Heckklimaanlage und erfahrenem Fahrer.",
    "Mid-size luxury coaster bus equipped with reclining seats, PA system, panoramic windows, and professional driver.": "Mittelgroßer Luxus-Coaster-Bus mit Verstellsitzen, Reiselautspechern, Panoramafenstern und professionellem Fahrer.",
    "Full-size luxury tourist coach with climate control AC, under-floor luggage compartments, USB charging ports, and tour assistant.": "Großer Luxus-Reisebus mit Klimaanlage, Unterflur-Gepäckfächern, USB-Ladeanschlüssen und Reiseassistenz.",
    "Premium 4WD SUV with leather interior, sunroof, and high ground clearance. Perfect for luxury private island tours.": "Premium-Allrad-SUV mit Lederausstattung, Schiebedach und hoher Bodenfreiheit. Perfekt für luxuriöse Inselführungen.",
    "Authentic Sri Lankan auto-rickshaw experience for short distance city tours and scenic coastal rides.": "Authentisches sri-lankisches Autorikscha-Erlebnis für kurze Stadtrundfahrten und malerische Küstenfahrten.",
