    "Climb the ancient 5th-century Sigiriya Rock Fortress (UNESCO World Heritage) and explore the sacred Dambulla Cave Temple complex featuring over 150 Buddha statues.": "Besteigen Sie die antike Felsenfestung Sigiriya aus dem 5. Jahrhundert (UNESCO-Weltkulturerbe) und erkunden Sie den heiligen Höhlentempelkomplex von Dambulla mit über 150 Buddha-Statuen.",
    "Ella Hill Country & Nine Arch Bridge Train": "Ella Bergland & Neun-Bogen-Brücke Zugfahrt",
    "Experience the world-famous blue train ride through lush tea plantations, marvel at Nine Arch Bridge, and hike Little Adam's Peak.": "Erleben Sie die weltberühmte Fahrt mit dem blauen Zug durch saftig grüne Teeplantagen, bewundern Sie die Neun-Bogen-Brücke und wandern Sie auf den Little Adam's Peak.",
    "Yala National Park Wild Leopard Safari": "Yala Nationalpark Wild-Leoparden-Safari",
    "Embark on an exciting 4x4 Jeep Safari in Yala, world-renowned for highest leopard density, wild elephants, sloth bears, and exotic birds.": "Begeben Sie sich auf eine aufregende 4x4-Jeep-Safari in Yala, das weltbekannt ist für die höchste Leopardendichte, wilde Elefanten, Lippenbären und exotische Vögel.",
    "Mirissa Blue Whale Watching & Galle Fort": "Mirissa Blauwal-Beobachtung & Festung Galle",
    "Sail into the Indian Ocean to spot Blue Whales and Dolphins, followed by a sunset walking tour of 16th-century Portuguese Galle Fort.": "Segeln Sie in den Indischen Ozean, um Blauwale und Delfine zu beobachten, gefolgt von einem Spaziergang bei Sonnenuntergang durch die portugiesische Festung Galle aus dem 16. Jahrhundert.",
    "Ancient Kingdoms & Heritage Discovery": "Antike Königreiche & Kulturerbe-Entdeckung",
    "Comprehensive week-long journey through Sri Lanka's ancient royal kingdoms, sacred temples, and UNESCO world heritage sites.": "Umfassende einwöchige Reise durch die antiken Königreiche Sri Lankas, heilige Tempel und UNESCO-Weltkulturerbestätten.",
