    "Architectural masterpiece integrated into a cliffside overlooking the Kandalama Lake and Sigiriya Rock.": "Architektonisches Meisterwerk an einer Klippe mit Blick auf den Kandalama-See und den Felsen von Sigiriya.",
    "Oceanfront luxury resort featuring a 18-hole golf course, expansive pools, and signature CHI spa.": "Luxusresort am Meer mit 18-Loch-Golfplatz, weitläufigen Pools und erstklassigem CHI Spa.",
