    "Hotel Package": "Hotelpaket",
    "At Premier Tour Booking, we believe flexibility is the key to perfect travel planning. Whether you want to stay in an ultra-luxurious overwater villa in the Maldives, wander the historic bazaars of Istanbul, or embark on a wild safari in Sri Lanka, we connect all details together to make it painless.": "Bei Premier Tour Booking glauben wir, dass Flexibilität der Schlüssel zur perfekten Reiseplanung ist. Egal, ob Sie in einer ultraluxuriösen Überwasservilla auf den Malediven übernachten, über die historischen Basare Istanbuls schlendern oder auf Safari in Sri Lanka gehen möchten, wir verbinden alle Details nahtlos miteinander.",
    "Our state-of-the-art booking system brings real-time rates directly from verified hotels, airlines, and premium vehicle operators, helping you secure the best prices with fully custom dates, and customizable payment structures.": "Unser hochmodernes Buchungssystem bietet Echtzeittarife direkt von verifizierten Hotels, Fluggesellschaften und Fahrzeuganbietern und hilft Ihnen, sich die besten Preise mit vollständig anpassbaren Daten und Zahlungsstrukturen zu sichern."
