    "Our Legacy": "Onze erfenis",
    "Our Mission & Story": "Onze missie & verhaal",
    "Learn about Premier Tour Booking's global commitment to handcrafting dream journeys.": "Ontdek de wereldwijde toewijding van Premier Tour Booking voor het handmatig samenstellen van droomreizen.",
    "Perfecting Travel Since 2018": "Perfect reizen sinds 2018",
    "Premier Tour Booking was established in 2018 with a humble, powerful vision: to take the complexity out of custom international travel. What began as a local boutique consultation firm has matured into a comprehensive digital portal servicing over 120,000 satisfied passengers globally.": "Premier Tour Booking is in 2018 opgericht met een bescheiden, krachtige visie: de complexiteit wegnemen uit gepersonaliseerde internationale reizen. Wat begon als een lokaal boutique adviesbureau is uitgegroeid tot een uitgebreid digitaal portaal dat wereldwijd meer dan 120.000 tevreden reizigers bedient.",
    "We specialize in bridging flights, bespoke hotel partnerships, guided adventures, and premium vehicle fleets into cohesive, flexible itineraries. By bypassing traditional middlemen, we are able to maintain a premium standard of services while extending best-in-market rates directly to our travelers.": "Wij zijn gespecialiseerd in het samenvoegen van vluchten, op maat gemaakte hotelpartnerschappen, begeleide avonturen en premium voertuigen tot coherente, flexibele reisschema's. Door traditionele tussenpersonen te omzeilen, kunnen we een premium servicestandaard handhaven en tegelijkertijd de scherpste tarieven in de markt rechtstreeks aanbieden aan onze reizigers.",
    "Our core values are anchored on transparency, environmental sustainability, and meticulous customer care. With 24/7 global client support centers and an active flight tracking network, we make sure that our passengers are covered at every mile of their voyage.": "Onze kernwaarden zijn verankerd in transparantie, ecologische duurzaamheid en nauwgezette zorg voor onze klanten. Met 24/7 wereldwijde ondersteuning en een actief vluchtvolgsysteem zorgen we ervoor dat onze passagiers op elke mijl van hun reis gedekt zijn.",
    "Our Standards": "Onze normen",
