    "At Premier Tour Booking, we believe flexibility is the key to perfect travel planning. Whether you want to stay in an ultra-luxurious overwater villa in the Maldives, wander the historic bazaars of Istanbul, or embark on a wild safari in Sri Lanka, we connect all details together to make it painless.": "Bij Premier Tour Booking geloven we dat flexibiliteit de sleutel is tot perfecte reisplanning. Of u nu in een ultraluxe overwatervilla op de Malediven wilt verblijven, door de historische bazaars van Istanbul wilt dwalen of op safari in Sri Lanka wilt gaan, wij regelen alles tot in de puntjes.",
