    "What is your refund and cancellation policy?": "返金およびキャンセルポリシーはどうなっていますか？",
    "How do I receive my booking confirmations and travel vouchers?": "予約確認書や旅行バウチャーはどのように受け取りますか？",
    "Our Legacy": "私たちの遺産",
    "Our Mission & Story": "ミッションと歩み",
    "Learn about Premier Tour Booking's global commitment to handcrafting dream journeys.": "夢のような旅を丁寧につくり上げる、プレミア・ツアー・ブッキングの世界的な取り組みについてご紹介します。",
    "Perfecting Travel Since 2018": "2018年から旅の感動を究め続ける",
    "Premier Tour Booking was established in 2018 with a humble, powerful vision: to take the complexity out of custom international travel. What began as a local boutique consultation firm has matured into a comprehensive digital portal servicing over 120,000 satisfied passengers globally.": "プレミア・ツアー・ブッキングは、オーダーメイドの海外旅行から搬雑さを取り除くという、ささやかでありながら力強いビジョンのもと、2018年に設立されました。地元のブティック・コンサルティング会社としてスタートした私たちは、現在、世界中で12万人以上の満足した旅客にサービスを提供する総合的なデジタルポータルへと成長しました。",
    "We specialize in bridging flights, bespoke hotel partnerships, guided adventures, and premium vehicle fleets into cohesive, flexible itineraries. By bypassing traditional middlemen, we are able to maintain a premium standard of services while extending best-in-market rates directly to our travelers.": "私たちは、航空便、特注の提携ホテル、ガイド付きアドベンチャー、高級車レンタルを統合し、まとまりのある柔軟な旅程を設計することを得意としています。伝統的な仲介業者を省くことで、プレミアムなサービス基準を維持しながら、市場最高のレートを旅行者に直接提供することができます。",
    "Our core values are anchored on transparency, environmental sustainability, and meticulous customer care. With 24/7 global client support centers and an active flight tracking network, we make sure that our passengers are covered at every mile of their voyage.": "私たちの核となる価値観は、透明性、環境への配慮、そしてきめ細かなカスタマーケアに支えられています。24時間年中無休の世界的なサポートセンターとアクティブなフライト追跡ネットワークにより、旅客のすべての旅路に寄り添い、安心をお届けします。",
    "Our Standards": "私たちのこだわり",
    "Why Choose Premier Tour": "プレミア・ツアーを選ぶ理由",
    "Four pillars that define our service excellence and travel quality.": "卓越したサービスと旅の品質を定義する4つの柱。",
    "Trusted Experience": "信頼の実績",
    "Over 8 years of continuous booking experience, verified tour experts, and ATOL/ABTA protected travel networks.": "8年以上にわたる安定した予約実績、厳選されたツアーエキスパート、ATOL/ABTAによる保護ネットワーク。",
    "24/7 Live Support": "24時間年中無休サポート",
