    "What is your refund and cancellation policy?": "退款和取消政策是什么？",
    "How do I receive my booking confirmations and travel vouchers?": "我如何收到预订确认函和旅行凭证？",
    "Our Legacy": "我们的传承",
    "Our Mission & Story": "我们的使命与历程",
    "Learn about Premier Tour Booking's global commitment to handcrafting dream journeys.": "了解 Premier Tour Booking 全球致力于打造梦想旅程的承诺。",
    "Perfecting Travel Since 2018": "自 2018 年起完美呈现每一次旅行",
    "Premier Tour Booking was established in 2018 with a humble, powerful vision: to take the complexity out of custom international travel. What began as a local boutique consultation firm has matured into a comprehensive digital portal servicing over 120,000 satisfied passengers globally.": "Premier Tour Booking 成立于 2018 年，拥有一个质朴而强大的愿景：为定制国际旅行化繁为简。从起初的一家当地精品咨询公司，如今已成长为一个服务全球超过 12 万名满意旅客的综合性数字化门户网站。",
    "We specialize in bridging flights, bespoke hotel partnerships, guided adventures, and premium vehicle fleets into cohesive, flexible itineraries. By bypassing traditional middlemen, we are able to maintain a premium standard of services while extending best-in-market rates directly to our travelers.": "我们专注于将机票、定制化合作伙伴酒店、有导游陪同的冒险项目和高档车队融合成具有高连贯性与灵活性的行程。通过绕过传统中间商，我们在向旅客直接提供市场最优价格的同时也保持了极高标准的服务。",
    "Our core values are anchored on transparency, environmental sustainability, and meticulous customer care. With 24/7 global client support centers and an active flight tracking network, we make sure that our passengers are covered at every mile of their voyage.": "我们的核心价值观植根于透明度、环境可持续性以及细致入微的客户关怀。凭借 24/7 全球客户支持中心和活跃的航班跟踪网络，我们确保旅客在旅程中的每一英里都得到万全保障。",
    "Our Standards": "我们的标准",
