    "Over 8 years of continuous booking experience, verified tour experts, and ATOL/ABTA protected travel networks.": "超过 8 年的持续预订运营经验、经过验证的旅行专家以及受 ATOL/ABTA 保障的旅行网络。",
    "24/7 Live Support": "24/7 在线支持",
