    "YOUR DREAM JOURNEY": "您的梦幻之旅",
    "At Premier Tour Booking, we believe flexibility is the key to perfect travel planning. Whether you want to stay in an ultra-luxurious overwater villa in the Maldives, wander the historic bazaars of Istanbul, or embark on a wild safari in Sri Lanka, we connect all details together to make it painless.": "在 Premier Tour Booking，我们相信灵活性是完美旅行计划的关键。无论您是想入住马尔代夫超豪华的水上别墅、漫步在伊斯坦布尔历史悠久的集市，还是在斯里兰卡开启疯狂的野生动物园之旅，我们都会将所有细节结合在一起，让您的旅途轻松无忧。",
    "Our state-of-the-art booking system brings real-time rates directly from verified hotels, airlines, and premium vehicle operators, helping you secure the best prices with fully custom dates, and customizable payment structures.": "我们最先进的预订系统直接从经过认证的酒店、航空公司和高级车辆运营商那里提供实时房价，帮助您以完全自定义的日期和可定制的支付结构获得最优惠的价格。",
