    "How do I receive my booking confirmations and travel vouchers?": "Как я получу подтверждение бронирования и ваучеры на поездку?",
    "Our Legacy": "Наше наследие",
    "Our Mission & Story": "Наша миссия и история",
    "Learn about Premier Tour Booking's global commitment to handcrafting dream journeys.": "Узнайте о глобальном стремлении Premier Tour Booking создавать путешествия вашей мечты.",
    "Perfecting Travel Since 2018": "Совершенствуем путешествия с 2018 года",
    "Premier Tour Booking was established in 2018 with a humble, powerful vision: to take the complexity out of custom international travel. What began as a local boutique consultation firm has matured into a comprehensive digital portal servicing over 120,000 satisfied passengers globally.": "Агентство Premier Tour Booking было основано в 2018 году со скромной, но вдохновляющей целью: избавить клиентов от сложностей при планировании индивидуальных поездок. То, что начиналось как локальное бутиковое агентство, превратилось в полноценный цифровой портал, обслуживший более 120 000 довольных путешественников по всему миру.",
    "We specialize in bridging flights, bespoke hotel partnerships, guided adventures, and premium vehicle fleets into cohesive, flexible itineraries. By bypassing traditional middlemen, we are able to maintain a premium standard of services while extending best-in-market rates directly to our travelers.": "Мы специализируемся на объединении авиабилетов, эксклюзивного партнерства с отелями, экскурсионных приключений и премиального автопарка в единые и гибкие маршруты. Исключая традиционных посредников, мы поддерживаем премиальный стандарт обслуживания, предлагая нашим путешественникам лучшие цены напрямую на рынке.",
    "Our core values are anchored on transparency, environmental sustainability, and meticulous customer care. With 24/7 global client support centers and an active flight tracking network, we make sure that our passengers are covered at every mile of their voyage.": "Наши ключевые ценности основаны на прозрачности, экологической устойчивости и тщательной заботе о клиентах. Благодаря круглосуточным центрам поддержки по всему миру и активной системе отслеживания авиарейсов, мы гарантируем безопасность наших пассажиров на каждом километре пути.",
    "Our Standards": "Наши стандарты",
    "Why Choose Premier Tour": "Почему выбирают Premier Tour",
    "Four pillars that define our service excellence and travel quality.": "Четыре столпа, определяющие качество наших путешествий и сервис.",
