    "Over 8 years of continuous booking experience, verified tour experts, and ATOL/ABTA protected travel networks.": "Более 8 лет стабильной работы по бронированию, верифицированные эксперты по турам и защищенные сети ATOL/ABTA.",
    "24/7 Live Support": "Круглосуточная поддержка",
