    "Your Message": "आपका संदेश",
    "Please specify dates, passenger details, or custom booking needs...": "कृपया तिथियां, यात्री विवरण, या कस्टम बुकिंग आवश्यकताओं को निर्दिष्ट करें...",
    "Submit Inquiry Form": "पूछताछ प्रपत्र जमा करें",
    "Frequently Asked Questions": "अक्सर पूछे जाने वाले प्रश्न",
    "What is your refund and cancellation policy?": "आपकी धनवापसी और रद्दीकरण नीति क्या है?",
    "How do I receive my booking confirmations and travel vouchers?": "मुझे मेरी बुकिंग पुष्टि और यात्रा वाउचर कैसे प्राप्त होंगे?",
    "Our Legacy": "हमारी विरासत",
    "Our Mission & Story": "हमारा उद्देश्य और कहानी",
    "Learn about Premier Tour Booking's global commitment to handcrafting dream journeys.": "सपनों की यात्राओं को तैयार करने के लिए प्रीमियर टूर बुकिंग की वैश्विक प्रतिबद्धता के बारे में जानें।",
    "Perfecting Travel Since 2018": "2018 से यात्रा को सिद्ध कर रहे हैं",
    "Premier Tour Booking was established in 2018 with a humble, powerful vision: to take the complexity out of custom international travel. What began as a local boutique consultation firm has matured into a comprehensive digital portal servicing over 120,000 satisfied passengers globally.": "प्रीमियम टूर बुकिंग की स्थापना 2018 में एक विनम्र, शक्तिशाली दृष्टि के साथ की गई थी: कस्टम अंतरराष्ट्रीय यात्रा से जटिलता को दूर करना। जो एक स्थानीय बुटीक परामर्श फर्म के रूप में शुरू हुआ था, वह वैश्विक स्तर पर 120,000 से अधिक संतुष्ट यात्रियों की सेवा करने वाले एक व्यापक डिजिटल पोर्टल के रूप में परिपक्व हो गया है।",
    "We specialize in bridging flights, bespoke hotel partnerships, guided adventures, and premium vehicle fleets into cohesive, flexible itineraries. By bypassing traditional middlemen, we are able to maintain a premium standard of services while extending best-in-market rates directly to our travelers.": "हम उड़ानों, बेस्पोक होटल साझेदारियों, निर्देशित कारनामों और प्रीमियम वाहन बेड़े को सामंजस्यपूर्ण, लचीले यात्रा कार्यक्रमों में जोड़ने में विशेषज्ञ हैं। पारंपरिक बिचौलियों को दरकिनार करके, हम अपने यात्रियों को सीधे बाजार में सर्वोत्तम दरें प्रदान करते हुए सेवाओं के प्रीमियम मानक को बनाए रखने में सक्षम हैं।",
    "Our core values are anchored on transparency, environmental sustainability, and meticulous customer care. With 24/7 global client support centers and an active flight tracking network, we make sure that our passengers are covered at every mile of their voyage.": "हमारे मूल मूल्य पारदर्शिता, पर्यावरणीय स्थिरता और सावधानीपूर्वक ग्राहक देखभाल पर टिके हैं। 24/7 वैश्विक ग्राहक सहायता केंद्रों और एक सक्रिय उड़ान ट्रैकिंग नेटवर्क के साथ, हम सुनिश्चित करते हैं कि हमारे यात्रियों को उनकी यात्रा के हर मील में सहायता मिले।",
    "Our Standards": "हमारे मानक",
    "Why Choose Premier Tour": "प्रीमियर टूर क्यों चुनें",
    "Four pillars that define our service excellence and travel quality.": "चार स्तंभ जो हमारी सेवा उत्कृष्टता और यात्रा गुणवत्ता को परिभाषित करते हैं।",
    "Trusted Experience": "विश्वसनीय अनुभव",
    "Over 8 years of continuous booking experience, verified tour experts, and ATOL/ABTA protected travel networks.": "8 से अधिक वर्षों का निरंतर बुकिंग अनुभव, सत्यापित टूर विशेषज्ञ, और ATOL/ABTA संरक्षित यात्रा नेटवर्क।",
    "24/7 Live Support": "24/7 लाइव सहायता",
    "Immediate concierge support in London, Dubai, and Singapore to handle cancellations or re-routing instantly.": "रद्दीकरण या मार्ग परिवर्तन को तुरंत संभालने के लिए लंदन, दुबई और सिंगापुर में तत्काल दरबान सहायता।",
    "Global Network": "वैश्विक नेटवर्क",
